#!/usr/bin/env python3
"""Generate the admin fingerprint probe parameters from the product root JSON."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
config = json.loads((root / 'model-fingerprint.json').read_text())
backend = root / 'backend/internal/service/account_fingerprint_defaults_gotocc.go'
backend.write_text(
    '// Code generated by tools/generate_model_fingerprint.py; DO NOT EDIT.\n'
    'package service\n\n'
    f'const accountFingerprintMaxOutputTokens = {config["max_output_tokens"]}\n'
    f'const accountFingerprintTimeoutSeconds = {config["request_timeout_seconds"]}\n'
    f'const accountFingerprintNonTextModelPattern = {json.dumps(config["non_text_model_pattern"])}\n'
    'var accountFingerprintUnsupportedPlatforms = []string{'
    + ', '.join(json.dumps(value) for value in config['unsupported_platforms']) + '}\n'
)
frontend = root / 'frontend/src/components/gotocc/fingerprint/parameters.gen.json'
frontend.parent.mkdir(parents=True, exist_ok=True)
frontend.write_text(json.dumps(config, ensure_ascii=False, indent=2) + '\n')
